create or replace function public.business_growth_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; return (with ci as(select ci.id,ci.user_id from check_ins ci join locations l on l.id=ci.location_id where l.business_id=p_business_id and ci.checked_in_at between p_start and p_end),rv as(select r.id from reviews r join locations l on l.id=r.location_id where l.business_id=p_business_id and r.created_at between p_start and p_end and r.status<>'hidden'),loc as(select count(*) locations,count(*) filter(where is_active) active_locations from locations where business_id=p_business_id) select jsonb_build_object('check_ins',(select count(*) from ci),'unique_users',(select count(distinct user_id) from ci),'reviews',(select count(*) from rv),'new_users',(select count(distinct ci.user_id) from ci join profiles p on p.id=ci.user_id where p.created_at between p_start and p_end),'locations',(select locations from loc),'active_locations',(select active_locations from loc))); end $$;
create or replace function public.business_promotion_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; return (with p as(select id,active from promotions where business_id=p_business_id),ev as(select ae.promotion_id,ae.event_type,ae.user_id from analytics_events ae join p on p.id=ae.promotion_id where ae.created_at between p_start and p_end) select jsonb_build_object('business_id',p_business_id,'promotions',(select count(*) from p),'active_promotions',(select count(*) from p where active),'promotion_views',(select count(*) from ev where event_type='promotion_view'),'redemptions',(select count(*) from ev where event_type='promotion_redeemed'),'unique_redeemers',(select count(distinct user_id) from ev where event_type='promotion_redeemed'),'conversion_rate_pct',case when (select count(*) from ev where event_type='promotion_view')=0 then 0 else round((100.0*(select count(*) from ev where event_type='promotion_redeemed')/(select count(*) from ev where event_type='promotion_view'))::numeric,2) end)); end $$;
create or replace function public.business_event_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; return (with ev as(select id from business_events where business_id=p_business_id and event_date between p_start::date and p_end::date),rs as(select count(distinct er.user_id) n from event_rsvps er where er.event_id in(select id from ev)),ae as(select count(*) filter(where event_type='location_view') views,count(*) filter(where event_type='event_rsvp') tracked_rsvps from analytics_events where event_id in(select id from ev) and created_at between p_start and p_end) select jsonb_build_object('events',(select count(*) from ev),'rsvps',(select n from rs),'event_views',(select views from ae),'event_rsvps_tracked',(select tracked_rsvps from ae))); end $$;
create or replace function public.business_growth_cockpit(p_business_id uuid,p_window_days integer default 30) returns jsonb language plpgsql stable security definer set search_path='public','auth','extensions','pg_temp' as $$ declare v_days integer:=least(greatest(coalesce(p_window_days,30),7),90); v_end timestamptz:=now(); v_start timestamptz; v_prev_start timestamptz; v_current jsonb; v_previous jsonb; v_promotions jsonb; v_campaigns jsonb; v_events jsonb; v_reviews jsonb; v_actions jsonb; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; v_start:=v_end-(v_days||' days')::interval; v_prev_start:=v_start-(v_days||' days')::interval; v_current:=public.business_growth_analytics(p_business_id,v_start,v_end); v_previous:=public.business_growth_analytics(p_business_id,v_prev_start,v_start); v_promotions:=public.business_promotion_analytics(p_business_id,v_start,v_end); v_campaigns:=public.business_campaign_analytics(p_business_id,v_start,v_end); v_events:=public.business_event_analytics(p_business_id,v_start,v_end); v_reviews:=public.business_review_analytics(p_business_id,v_start,v_end); v_actions:=public.get_business_growth_action_summary(p_business_id); return jsonb_build_object('business_id',p_business_id,'window_days',v_days,'window',jsonb_build_object('start',v_start,'end',v_end),'current',v_current,'previous',v_previous,'delta',jsonb_build_object('check_ins',coalesce((v_current->>'check_ins')::int,0)-coalesce((v_previous->>'check_ins')::int,0),'unique_users',coalesce((v_current->>'unique_users')::int,0)-coalesce((v_previous->>'unique_users')::int,0),'reviews',coalesce((v_current->>'reviews')::int,0)-coalesce((v_previous->>'reviews')::int,0),'new_users',coalesce((v_current->>'new_users')::int,0)-coalesce((v_previous->>'new_users')::int,0)),'promotions',v_promotions,'campaigns',v_campaigns,'events',v_events,'reviews',v_reviews,'growth_actions',v_actions,'generated_at',now()); end $$;
revoke all on function public.business_growth_analytics(uuid,timestamptz,timestamptz) from public,anon; revoke all on function public.business_promotion_analytics(uuid,timestamptz,timestamptz) from public,anon; revoke all on function public.business_event_analytics(uuid,timestamptz,timestamptz) from public,anon; revoke all on function public.business_growth_cockpit(uuid,integer) from public,anon; grant execute on function public.business_growth_analytics(uuid,timestamptz,timestamptz) to authenticated; grant execute on function public.business_promotion_analytics(uuid,timestamptz,timestamptz) to authenticated; grant execute on function public.business_event_analytics(uuid,timestamptz,timestamptz) to authenticated; grant execute on function public.business_growth_cockpit(uuid,integer) to authenticated;
